typedef unsigned short uint16;
typedef unsigned int uint32;

class vector2d
{
public:
  vector2d() {}
  vector2d(float _x, float _y) : x(_x), y(_y) {}
  float x, y;
};

class texture_coord : public vector2d
{
public:
  texture_coord() {}
  texture_coord(float _u, float _v) : vector2d(_u, _v) {}
};

class vector3d
{
public:
  float x, y, z;
};

class color32
{
public:
  uint32 i;
};

class matrix4x4;
extern const matrix4x4 identity_matrix;

class material
{
public:
  void send_context(int, int, unsigned int, color32 = color32());
};

class game
{
public:
  material *get_blank_material() const;
};

class app
{
public:
  static app *inst();
  game *get_game() const;
};

class geometry_manager
{
public:
  enum xform_t
  {
    XFORM_LOCAL_TO_WORLD
  };
  static geometry_manager *inst();
  void set_xform(xform_t, const matrix4x4 &);
  void set_local_to_world(const matrix4x4 &_x)
  {
    set_xform(XFORM_LOCAL_TO_WORLD, _x);
  }
};

class hw_rasta_vert
{
};

class hw_rasta_vert_lit
{
public:
  vector3d xyz;
  float reserved;
  color32 diffuse;
  color32 specular;
  unsigned char bone_ids[4];
  float bone_weights[4];
  vector2d tc[2];
};

class vert_buf
{
public:
  uint32 count;
  hw_rasta_vert *verts;
  int max_size;
  bool locked;
  bool optimized;

  void lock(int, int = 0);
  void unlock();
  hw_rasta_vert *begin() const { return verts; }
};

extern vert_buf vert_workspace;

class hw_rasta
{
public:
  static hw_rasta *inst();
  void send_indexed_vertex_list(
      const vert_buf &, int, const unsigned short *, int, unsigned = 0);
};

enum
{
  MAP_DIFFUSE = 0,
  FORCE_TRANSLUCENCY = 0x0100
};

void render_quad(const vector3d &pt1, const vector3d &pt2, const vector3d &pt3, const vector3d &pt4,
                 color32 col, bool double_sided)
{
  app::inst()->get_game()->get_blank_material()->send_context(0, MAP_DIFFUSE, FORCE_TRANSLUCENCY);
  static const uint16 debug_render_indices[12]=
  {
    0,1,2, 0,2,3,      // front
    0,2,1, 0,3,2,      // back
  };
  uint32 num_indices=double_sided ? 12 : 6;
  uint32 num_verts=4;

  geometry_manager::inst()->set_local_to_world(identity_matrix);

  vert_workspace.lock(4);
  hw_rasta_vert_lit * vert_it = (hw_rasta_vert_lit*)vert_workspace.begin();

  vert_it->xyz = pt1;
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(0.0f,0.0f);
  ++vert_it;

  vert_it->xyz = pt2;
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(0.0f,1.0f);
  ++vert_it;

  vert_it->xyz = pt3;
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(1.0f,1.0f);
  ++vert_it;

  vert_it->xyz = pt4;
  vert_it->diffuse = col;
  vert_it->tc[0] = texture_coord(1.0f,0.0f);
  ++vert_it;

  vert_workspace.unlock();

  // send it to the card (using list because it could be double-sided)
  hw_rasta::inst()->send_indexed_vertex_list(vert_workspace, num_verts,
    debug_render_indices, num_indices);
}
